DROP TABLE static.company_targets;

CREATE TABLE static.company_targets 
(
    planning_month	DATE ENCODE ZSTD,
    month	DATE ENCODE ZSTD,
    stakeholder	VARCHAR(512),
    segment	VARCHAR(512),
    metric	VARCHAR(512),
    value	DOUBLE PRECISION ENCODE ZSTD,
    value_format	VARCHAR(512)
);

GRANT SELECT ON static.company_targets to GROUP reader;

